SELECT symbol, interval_code, status, COUNT(*) AS work_rows, MAX(updated_at) AS latest_updated_ksa, MAX(completed_at) AS latest_completed_ksa, MAX(failure_stage) AS latest_failure_stage, MAX(error_message) AS sample_error FROM signal_processing_work WHERE candle_open_time >= NOW() - INTERVAL 90 MINUTE GROUP BY symbol, interval_code, status ORDER BY latest_updated_ksa DESC, symbol, interval_code, status